public static void printPairs(int[] nums){
    int tp = 0;
    for (int i=0; i<nums.length; i++){
        int curr = nums[i];
        for (int j=i+1; j<nums.length; j++){
            System.out.print("("+curr+","+nums[j]+")");
            tp++;
        }
        System.out.println();
    }
    System.out.println("Total number of pairs: "+ tp);
}
